import {construct} from './geometry.js';
import {detectCircle,detectOcean} from './detection.js';
const $=id=>document.getElementById(id),canvas=$('mapCanvas'),ctx=canvas.getContext('2d');
let image=null,zone={x:421,y:467,r:244},angle=225,guides=true,pickOcean=false,drag=null,fileName='Example map',initial=null,revision=0,job=0;
let worker=null;const pending=new Map();
try{worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{const p=pending.get(data.id);if(p){pending.delete(data.id);data.error?p.reject(new Error(data.error)):p.resolve(data.result)}};worker.onerror=()=>{for(const p of pending.values())p.reject(new Error('Automatic analysis unavailable. Use the circle handles and ocean direction.'));pending.clear();worker.terminate();worker=null;};}catch{}
function notify(text){$('message').textContent=text;}
function controls(){if(!image)return;for(const [id,key]of [['centerX','x'],['centerY','y'],['radius','r']])$(id).value=Math.round(zone[key]);$('centerX').max=image.naturalWidth;$('centerY').max=image.naturalHeight;$('radius').max=Math.max(image.naturalWidth,image.naturalHeight);$('angle').value=angle;$('angleValue').textContent=`${Math.round(angle)}°`;$('compassNeedle').style.transform=`rotate(${angle}deg)`;$('direction').value=angle%45===0?String(angle):'custom';$('guideButton').classList.toggle('active',guides);$('guideButton').setAttribute('aria-pressed',String(guides));$('pickOceanButton').classList.toggle('active',pickOcean);$('pickOceanButton').textContent=pickOcean?'Click toward the ocean…':'Pick ocean on map';}
function strokeCircle(c,center,r,color,width){c.beginPath();c.arc(center.x,center.y,r,0,Math.PI*2);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
function render(target=ctx,editing=true){if(!image)return;target.clearRect(0,0,image.naturalWidth,image.naturalHeight);target.drawImage(image,0,0);const size=Math.min(image.naturalWidth,image.naturalHeight),line=Math.max(3,size*.004),g=construct(zone,angle);target.save();target.lineCap='round';
  if(guides){target.strokeStyle='#08101b';target.lineWidth=line+2;target.beginPath();target.moveTo(g.endpoints[0].x,g.endpoints[0].y);target.lineTo(g.endpoints[1].x,g.endpoints[1].y);target.stroke();target.strokeStyle='#ecf9ff';target.lineWidth=Math.max(1,line*.45);target.stroke();for(const p of [g.ocean,g.inland]){const t=zone.r*.085;target.strokeStyle='#08101b';target.lineWidth=line+2;target.beginPath();target.moveTo(p.x-g.perpendicular.x*t,p.y-g.perpendicular.y*t);target.lineTo(p.x+g.perpendicular.x*t,p.y+g.perpendicular.y*t);target.stroke();target.strokeStyle='#ecf9ff';target.lineWidth=Math.max(1,line*.45);target.stroke();}}
  if(editing){strokeCircle(target,zone,zone.r,'#ffffffaa',Math.max(1,line*.45));}
  strokeCircle(target,g.prediction,g.prediction.r,'#ff3047',line*1.5);
  if(editing){const handles=[{x:zone.x,y:zone.y},{x:zone.x+zone.r,y:zone.y}];for(const p of handles){target.beginPath();target.arc(p.x,p.y,size*.009,0,Math.PI*2);target.fillStyle='#0b101c';target.fill();target.strokeStyle='#83e7ed';target.lineWidth=Math.max(2,line*.65);target.stroke();}target.beginPath();target.arc(g.ocean.x,g.ocean.y,Math.max(2,size*.003),0,Math.PI*2);target.fillStyle='#ff3047';target.fill();}
  target.restore();}
function update(){controls();render();}
function analysisImage(){const ratio=Math.min(1,650/Math.max(image.naturalWidth,image.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(image.naturalWidth*ratio);c.height=Math.round(image.naturalHeight*ratio);const a=c.getContext('2d',{willReadFrequently:true});a.drawImage(image,0,0,c.width,c.height);return{image:a.getImageData(0,0,c.width,c.height),ratio};}
async function analyze(action){const {image:im,ratio}=analysisImage();const scaledZone={x:zone.x*ratio,y:zone.y*ratio,r:zone.r*ratio};if(!worker){await new Promise(r=>setTimeout(r,10));return{result:action==='circle'?detectCircle(im):detectOcean(im,scaledZone),ratio};}const id=++job;return await new Promise((resolve,reject)=>{pending.set(id,{resolve:result=>resolve({result,ratio}),reject});worker.postMessage({id,action,image:im,zone:scaledZone},[im.data.buffer]);});}
function busy(on){$('busy').hidden=!on;$('detectButton').disabled=on;$('oceanButton').disabled=on;}
async function detect(){if(!image)return;const version=revision;busy(true);try{const {result,ratio}=await analyze('circle');if(version!==revision)return;zone={x:result.x/ratio,y:result.y/ratio,r:result.r/ratio};$('detectionStatus').textContent=result.score>.8?'White boundary detected · check handles':'Boundary estimated · verify the circle';update();notify('White circle detected. Check its outline, then set the ocean direction.');}catch(e){if(version===revision){$('detectionStatus').textContent='Manual adjustment needed';notify(e.message);}}finally{if(version===revision)busy(false);}}
async function findOcean(silent=false){if(!image)return;const version=revision;try{const {result}=await analyze('ocean');if(version!==revision)return;angle=result.angle;update();if(!silent)notify('Ocean side estimated from blue map pixels. Confirm the direction or click the coastline.');}catch(e){if(!silent&&version===revision)notify(e.message);}}
async function loadImage(source,name,example=false){const thisRevision=++revision;busy(true);pickOcean=false;const next=new Image();next.onload=async()=>{if(thisRevision!==revision)return;image=next;fileName=name;canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;$('mapName').textContent=name;zone=example?{x:421,y:467,r:244}:{x:canvas.width/2,y:canvas.height/2,r:Math.min(canvas.width,canvas.height)*.27};angle=example?225:180;initial={zone:{...zone},angle};update();busy(false);if(example){$('detectionStatus').textContent='Example circle loaded';notify('Upload or paste your map to begin.');}else{await detect();if(thisRevision===revision){await findOcean(true);initial={zone:{...zone},angle};notify('Map ready. Verify the white circle and ocean side before exporting.');}}};next.onerror=()=>{if(thisRevision===revision){busy(false);notify('Could not read this image. Try a PNG, JPG, WebP, or BMP screenshot.');}};next.src=source;}
function upload(file){if(!file)return;if(!/^image\/(png|jpeg|webp|bmp|x-ms-bmp)$/.test(file.type)&&!(/\.(png|jpe?g|webp|bmp)$/i.test(file.name))){notify('Choose a PNG, JPG, WebP, or BMP image.');return;}if(file.size>35*1024*1024){notify('This image is too large. Use a screenshot smaller than 35 MB.');return;}const reader=new FileReader();reader.onload=()=>loadImage(reader.result,file.name);reader.onerror=()=>notify('The image could not be opened. Please try another file.');reader.readAsDataURL(file);}
$('uploadButton').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{upload(e.target.files[0]);e.target.value='';};$('detectButton').onclick=detect;$('oceanButton').onclick=()=>findOcean();$('exampleButton').onclick=()=>loadImage('assets/example-map.png','Example map',true);$('guideButton').onclick=()=>{guides=!guides;update();};$('resetButton').onclick=()=>{if(!initial)return;zone={...initial.zone};angle=initial.angle;guides=true;pickOcean=false;update();notify('Circle and direction reset.');};$('fullButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.map-panel').requestFullscreen();}catch{notify('Fullscreen is unavailable in this browser.');}};
for(const [id,key]of [['centerX','x'],['centerY','y'],['radius','r']])$(id).onchange=e=>{if(!image)return;let value=Number(e.target.value);if(!Number.isFinite(value)||e.target.value===''){controls();return;}const max=key==='x'?canvas.width:key==='y'?canvas.height:Math.max(canvas.width,canvas.height);zone[key]=Math.max(key==='r'?5:0,Math.min(max,value));update();};
$('direction').onchange=e=>{if(e.target.value!=='custom'){angle=Number(e.target.value);update();}};$('angle').oninput=e=>{angle=Number(e.target.value);update();};$('pickOceanButton').onclick=()=>{pickOcean=!pickOcean;controls();notify(pickOcean?'Click on the map toward the nearest ocean.':'Ocean picking canceled.');};
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};}
canvas.onpointerdown=e=>{if(!image||!$('busy').hidden)return;const p=point(e);if(pickOcean){angle=(Math.atan2(p.y-zone.y,p.x-zone.x)*180/Math.PI+360)%360;pickOcean=false;update();notify('Ocean direction set. Your prediction is ready.');return;}const threshold=22*canvas.width/canvas.getBoundingClientRect().width;if(Math.hypot(p.x-zone.x,p.y-zone.y)<threshold)drag={type:'center',dx:p.x-zone.x,dy:p.y-zone.y};else if(Math.hypot(p.x-(zone.x+zone.r),p.y-zone.y)<threshold||Math.abs(Math.hypot(p.x-zone.x,p.y-zone.y)-zone.r)<threshold*.55)drag={type:'radius'};if(drag)canvas.setPointerCapture(e.pointerId);};
canvas.onpointermove=e=>{if(!drag)return;const p=point(e);if(drag.type==='center'){zone.x=Math.max(0,Math.min(canvas.width,p.x-drag.dx));zone.y=Math.max(0,Math.min(canvas.height,p.y-drag.dy));}else zone.r=Math.max(5,Math.min(Math.max(canvas.width,canvas.height),Math.hypot(p.x-zone.x,p.y-zone.y)));$('detectionStatus').textContent='Circle adjusted manually';update();};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;};canvas.onkeydown=e=>{if(!image)return;const step=e.shiftKey?10:1;const keys={ArrowLeft:['x',-step],ArrowRight:['x',step],ArrowUp:['y',-step],ArrowDown:['y',step]};if(keys[e.key]){e.preventDefault();const[k,d]=keys[e.key];zone[k]=Math.max(0,Math.min(k==='x'?canvas.width:canvas.height,zone[k]+d));update();}};
$('exportButton').onclick=()=>{if(!image)return;const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;render(out.getContext('2d'),false);out.toBlob(blob=>{if(!blob){notify('Export failed. Try uploading the image again.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName==='Example map'?'zone-prediction.png':`${fileName.replace(/\.[^.]+$/,'')}-prediction.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Prediction downloaded at the original image resolution.');},'image/png');};
const stage=$('mapStage');let dropDepth=0;stage.ondragenter=e=>{e.preventDefault();dropDepth++;$('dropOverlay').hidden=false;};stage.ondragover=e=>e.preventDefault();stage.ondragleave=e=>{e.preventDefault();if(--dropDepth<=0){dropDepth=0;$('dropOverlay').hidden=true;}};stage.ondrop=e=>{e.preventDefault();dropDepth=0;$('dropOverlay').hidden=true;upload(e.dataTransfer.files[0]);};document.addEventListener('paste',e=>{const file=Array.from(e.clipboardData?.items??[]).find(i=>i.type.startsWith('image/'))?.getAsFile();if(file){e.preventDefault();upload(file);}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&pickOcean){pickOcean=false;controls();notify('Ocean picking canceled.');}});
const help=$('helpDialog');$('helpButton').onclick=()=>help.showModal();$('closeHelp').onclick=$('helpDone').onclick=()=>help.close();help.addEventListener('click',e=>{if(e.target===help){const r=help.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)help.close();}});
// Optional browser agent interface uses exactly the visible editor state.
if(document.modelContext?.registerTool){const context=document.modelContext;try{Promise.resolve(context.registerTool({name:'configure_zone_prediction',description:'Set the visible zone circle and ocean direction on the currently loaded map. Coordinates are original-image pixels.',inputSchema:{type:'object',properties:{x:{type:'number'},y:{type:'number'},radius:{type:'number'},angle:{type:'number'}},required:['x','y','radius','angle'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!image)throw new Error('Load a map first.');const{x,y,radius,angle:a}=input??{};if(![x,y,radius,a].every(Number.isFinite)||x<0||x>canvas.width||y<0||y>canvas.height||radius<5||radius>Math.max(canvas.width,canvas.height)||a<0||a>=360)throw new Error('Circle or angle is outside the image bounds.');zone={x,y,r:radius};angle=a;update();return construct(zone,angle).prediction;}})).catch(()=>{});}catch{}}
loadImage('assets/example-map.png','Example map',true);
// Generated brand asset is optional for offline portability; favicon remains a safe fallback.
const logo=new Image();logo.onload=()=>{$('brandLogo').src=logo.src};logo.src='assets/logo.png';
